"""Request schema validation for the branchable experiment protocol.

Anything that does not satisfy PROTOCOL.md raises :class:`ValueError`, which
the entry point turns into ``{"error":"invalid"}``.  The published whole-batch
bounds are checked from the input only, so a malformed batch can never drive
the engine into unbounded work.
"""

MAX_ID = 2147483647
MAX_RUNS = 8
MAX_OPERATIONS = 100000
MAX_ENQUEUES = 60000
MAX_SAVES = 64
MAX_RANGES = 64
MAX_TABLE = 10000

COMMANDS = frozenset(('enqueue', 'dequeue', 'sample', 'repartition', 'cancel',
                      'inspect', 'weight', 'save', 'restore'))


def _int(value):
    if type(value) is not int:
        raise ValueError('integer field required')
    return value


def _bounded(value, low, high):
    value = _int(value)
    if value < low or value > high:
        raise ValueError('integer out of range')
    return value


def _borders(value, label):
    if not isinstance(value, list) or len(value) < 2 or len(value) > MAX_RANGES + 1:
        raise ValueError('bad %s borders' % label)
    out = []
    previous = None
    for item in value:
        point = _bounded(item, 0, MAX_ID)
        if previous is not None and point <= previous:
            raise ValueError('borders must strictly increase')
        previous = point
        out.append(point)
    if out[0] != 0 or out[-1] < 1:
        raise ValueError('borders must span [0, U]')
    return out


def _pairs(value, label, low, high):
    if not isinstance(value, list) or len(value) > MAX_TABLE:
        raise ValueError('bad %s table' % label)
    table = {}
    for entry in value:
        if not isinstance(entry, list) or len(entry) != 2:
            raise ValueError('bad %s table entry' % label)
        flow = _bounded(entry[0], 0, MAX_ID)
        amount = _bounded(entry[1], low, high)
        if flow in table:
            raise ValueError('duplicate flow in %s table' % label)
        table[flow] = amount
    return table


def _policy(value):
    if not isinstance(value, dict):
        raise ValueError('policy object required')
    kind = value.get('kind')
    if kind == 'fifo':
        return ('fifo',)
    if kind == 'sff':
        return ('sff',)
    if kind == 'sp':
        return ('sp', _pairs(value.get('levels'), 'sp level', 0, MAX_ID))
    if kind == 'wfq':
        return ('wfq', _pairs(value.get('weights'), 'wfq weight', 1, 1024))
    raise ValueError('unknown policy kind')


def _events(value, policy):
    if not isinstance(value, list):
        raise ValueError('event array required')
    kind = policy[0]
    flows = policy[1] if kind in ('sp', 'wfq') else None
    ids = set()
    names = set()
    operations = 0
    enqueues = 0
    out = []
    for command in value:
        if not isinstance(command, list) or not command:
            raise ValueError('command array required')
        head = command[0]
        if not isinstance(head, str) or head not in COMMANDS:
            raise ValueError('unknown command')
        if head == 'enqueue':
            if len(command) != 5:
                raise ValueError('enqueue arity')
            pktid = _bounded(command[1], 0, MAX_ID)
            flow = _bounded(command[2], 0, MAX_ID)
            length = _bounded(command[3], 1, 1000000)
            size = _bounded(command[4], 0, MAX_ID)
            if pktid in ids:
                raise ValueError('duplicate enqueue id')
            ids.add(pktid)
            if flows is not None and flow not in flows:
                raise ValueError('undeclared flow')
            out.append(('enqueue', pktid, flow, length, size))
            operations += 1
            enqueues += 1
        elif head == 'dequeue':
            if len(command) != 2:
                raise ValueError('dequeue arity')
            visits = _bounded(command[1], 1, MAX_OPERATIONS)
            out.append(('dequeue', visits))
            operations += visits
        elif head == 'sample':
            if len(command) != 1:
                raise ValueError('sample arity')
            out.append(('sample',))
            operations += 1
        elif head == 'repartition':
            if len(command) != 2:
                raise ValueError('repartition arity')
            out.append(('repartition', _borders(command[1], 'repartition')))
            operations += 1
        elif head in ('cancel', 'inspect'):
            if len(command) != 2:
                raise ValueError('%s arity' % head)
            out.append((head, _bounded(command[1], 0, MAX_ID)))
            operations += 1
        elif head == 'weight':
            if len(command) != 3:
                raise ValueError('weight arity')
            if kind != 'wfq':
                raise ValueError('weight reconfiguration is wfq only')
            flow = _bounded(command[1], 0, MAX_ID)
            if flow not in flows:
                raise ValueError('undeclared flow')
            out.append(('weight', flow, _bounded(command[2], 1, 1024)))
            operations += 1
        else:  # save / restore
            if len(command) != 2:
                raise ValueError('%s arity' % head)
            name = _bounded(command[1], 0, MAX_ID)
            names.add(name)
            out.append((head, name))
            operations += 1
    if operations > MAX_OPERATIONS:
        raise ValueError('operation bound exceeded')
    if enqueues > MAX_ENQUEUES:
        raise ValueError('enqueue bound exceeded')
    if len(names) > MAX_SAVES:
        raise ValueError('checkpoint name bound exceeded')
    return out


def validate_request(request):
    """Return normalized run configurations, or raise ValueError."""
    if not isinstance(request, dict):
        raise ValueError('request object required')
    runs = request.get('runs')
    if not isinstance(runs, list):
        raise ValueError('runs array required')
    if len(runs) > MAX_RUNS:
        raise ValueError('run bound exceeded')
    configs = []
    for run in runs:
        if not isinstance(run, dict):
            raise ValueError('run object required')
        policy = _policy(run.get('policy'))
        configs.append({
            'banks': _bounded(run.get('banks'), 1, 16),
            'load_balancers': _bounded(run.get('load_balancers'), 1, 8),
            'fifo_bytes': _bounded(run.get('fifo_bytes'), 1, MAX_ID),
            'pifo_bytes': _bounded(run.get('pifo_bytes'), 1, MAX_ID),
            'refill_batch': _bounded(run.get('refill_batch'), 1, 32),
            'sample_period': _bounded(run.get('sample_period'), 1, 100000),
            'borders': _borders(run.get('borders'), 'run'),
            'policy': policy,
            'events': _events(run.get('events'), policy),
        })
    return configs
